function Get-BackupMenuFoldersAtLayer {
    param(
        [Parameter(Mandatory)][string]$Path,
        [Parameter(Mandatory)][ValidateRange(2, 64)][int]$Layer,
        [ValidateRange(1, 64)][int]$SchemaVersion = (Get-BackupMenuTraversalSchemaVersion)
    )

    $projectPath = Resolve-BackupDockerProjectPath -Path $Path
    $folders = @(Get-ChildItem -Path $projectPath -Directory -ErrorAction SilentlyContinue)
    if (-not $folders) {
        Write-Warning "No child folders found under: $projectPath"
        return @()
    }

